-- ═══ public.claim_nation(uuid, text)  — from 20250101000113_claim_nation.sql
create or replace function public.claim_nation(p_game_id uuid, p_nation text)
returns void as $$
declare
  g   public.games;
  uid text;
begin
  select * into g from public.games where id = p_game_id;
  if g is null then raise exception 'Game not found'; end if;
  if g.phase <> 'lobby' then raise exception 'Game has already started'; end if;

  uid := auth.uid()::text;
  if not (g.players ? uid) then raise exception 'You are not a player in this game'; end if;

  if p_nation is null then
    -- release the caller's current power
    update public.games
       set players = players #- array[uid, 'nation'], updated_at = now()
     where id = p_game_id;
    return;
  end if;

  -- reject if another player already holds this power
  if exists (
    select 1 from jsonb_each(g.players) e
    where e.key <> uid and e.value ->> 'nation' = p_nation
  ) then
    raise exception 'That power is already taken';
  end if;

  update public.games
     set players = jsonb_set(players, array[uid, 'nation'], to_jsonb(p_nation)),
         updated_at = now()
   where id = p_game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.commit_board(uuid, jsonb, jsonb, jsonb)  — from 20250101000141_draw_votes.sql
-- ── commit_board (re-issues 136): a committed board clears any agreed result ──
create or replace function public.commit_board(
  p_game_id    uuid,
  p_snapshot   jsonb,
  p_round      jsonb,
  p_ready_init jsonb
)
returns void as $$
begin
  update public.games
     set snapshot     = p_snapshot,
         phase        = p_round ->> 'phase',
         season       = p_round ->> 'season',
         year         = (p_round ->> 'year')::int,
         deadline     = case when p_round ->> 'phase' = 'complete' then null
                             else public.phase_deadline(settings, p_round ->> 'phase', now()) end,
         ready        = coalesce(p_ready_init, '{}'::jsonb),
         result       = null,
         resolving_at = null,
         updated_at   = now()
   where id = p_game_id;
end;
$$ language plpgsql;

-- ═══ public.create_named_channel(uuid, text[], text)  — from 20250101000131_reuse_helpers.sql
create or replace function public.create_named_channel(
  p_game_id uuid,
  p_members text[],
  p_name    text
) returns public.chat_channels as $$
declare
  canonical text[];
  ch        public.chat_channels;
begin
  if public.is_gunboat(p_game_id) then
    raise exception 'Press is disabled in this game (gunboat)';
  end if;

  canonical := public.canonical_channel_members(p_game_id, p_members);

  if p_name is null or length(trim(p_name)) = 0 then raise exception 'A name is required'; end if;
  if length(p_name) > 60 then raise exception 'Name too long (max 60 characters)'; end if;

  insert into public.chat_channels (game_id, members, is_public, name)
  values (p_game_id, canonical, false, trim(p_name))
  returning * into ch;

  return ch;
end;
$$ language plpgsql security definer;

-- ═══ public.create_public_channel()  — from 20250101000134_sql_helpers.sql
-- create_public_channel (re-issues 127).
create or replace function public.create_public_channel()
returns trigger as $$
declare nations text[];
begin
  if public.setting_bool(new.settings, 'gunboat', false) then
    return new;  -- gunboat: no press, no public channel
  end if;

  nations := public.game_nations(new.players);

  if coalesce(array_length(nations, 1), 0) >= 1 then
    insert into public.chat_channels (game_id, members, is_public)
    values (new.id, nations, true)
    on conflict (game_id, members) where name is null do nothing;
  end if;
  return new;
end;
$$ language plpgsql security definer;

