-- ═══ public.draw_outcome(games)  — from 20250101000141_draw_votes.sql
-- The set the survivors have agreed on, or null.
create or replace function public.draw_outcome(g public.games)
returns text[] as $$
declare
  alive text[] := public.surviving_nations(g);
  n     text;
  m     text;
  cand  text[];
  ok    boolean;
begin
  if cardinality(alive) = 0 then return null; end if;
  foreach n in array alive loop
    cand := public.draw_vote_set(g.id, n, alive);
    continue when cand is null;
    ok := true;
    foreach m in array alive loop
      if m = any(cand) then
        ok := public.draw_vote_set(g.id, m, alive) is not distinct from cand;
      else
        ok := public.draw_vote_set(g.id, m, alive) is null;
      end if;
      exit when not ok;
    end loop;
    if ok then return cand; end if;
  end loop;
  return null;
end;
$$ language plpgsql stable;

-- ═══ public.draw_vote_set(uuid, text, text[])  — from 20250101000141_draw_votes.sql
-- A survivor's effective vote: null = concede; otherwise its tie set restricted to the
-- survivors (sorted). No row = solo = {nation}.
create or replace function public.draw_vote_set(p_game_id uuid, p_nation text, p_alive text[])
returns text[] as $$
declare
  v public.draw_votes;
begin
  select * into v from public.draw_votes where game_id = p_game_id and nation = p_nation;
  if not found then return array[p_nation]; end if;
  if v.members is null then return null; end if;
  return (select array_agg(m order by m) from unnest(v.members) m where m = any(p_alive));
end;
$$ language plpgsql stable;

-- ═══ public.fire_adjudicator(uuid, jsonb, boolean)  — from 20250101000131_reuse_helpers.sql
create function public.fire_adjudicator(
  p_game_id uuid,
  p_body    jsonb   default '{}',
  p_strict  boolean default true
)
returns boolean as $$
declare cfg private.engine_config;
begin
  select * into cfg from private.engine_config where id;
  if cfg is null then
    if p_strict then raise exception 'The adjudicator is not configured'; end if;
    return false;
  end if;

  update public.games set resolving_at = now() where id = p_game_id;
  perform net.http_post(
    url     := cfg.function_url,
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'Authorization', 'Bearer ' || cfg.service_key),
    body    := jsonb_build_object('game_id', p_game_id) || coalesce(p_body, '{}'::jsonb)
  );
  return true;
end;
$$ language plpgsql security definer;

-- ═══ public.first_turn_deadline(jsonb, timestamptz)  — from 20250101000143_first_turn.sql
create or replace function public.first_turn_deadline(p_settings jsonb, p_from timestamptz)
returns timestamptz as $$
  select coalesce(
    p_from + make_interval(mins => nullif(greatest(0, (p_settings ->> 'first_turn')::int), 0)),
    public.phase_deadline(p_settings, 'movement', p_from));
$$ language sql stable;

-- ═══ public.game_nations(jsonb)  — from 20250101000134_sql_helpers.sql
-- The nations assigned in a players map: sorted, distinct; null when none.
create or replace function public.game_nations(p_players jsonb)
returns text[] as $$
  select array_agg(distinct value ->> 'nation' order by value ->> 'nation')
    from jsonb_each(p_players)
   where value ->> 'nation' is not null;
$$ language sql immutable;

-- ═══ public.get_or_create_channel(uuid, text[])  — from 20250101000131_reuse_helpers.sql
create or replace function public.get_or_create_channel(
  p_game_id uuid,
  p_members text[]
) returns public.chat_channels as $$
declare
  canonical text[];
  ch        public.chat_channels;
begin
  if public.is_gunboat(p_game_id) then
    raise exception 'Press is disabled in this game (gunboat)';
  end if;

  canonical := public.canonical_channel_members(p_game_id, p_members);

  insert into public.chat_channels (game_id, members, is_public)
  values (p_game_id, canonical, false)
  on conflict (game_id, members) where name is null do nothing;

  select * into ch from public.chat_channels
   where game_id = p_game_id and members = canonical and name is null;

  return ch;
end;
$$ language plpgsql security definer;

