-- ═══ public.join_public_game(uuid)  — from 20250101000146_drop_avatar_url.sql
create or replace function public.join_public_game(game_id uuid)
returns jsonb as $$
declare
  game_row     public.games;
  player_count int;
  max_players  int;
  user_meta    jsonb;
  player_info  jsonb;
begin
  select * into game_row from public.games where id = game_id;

  if game_row is null then
    raise exception 'Game not found';
  end if;

  if game_row.phase != 'lobby' then
    raise exception 'Game is not accepting players';
  end if;

  if game_row.players ? (auth.uid()::text) then
    return game_row.players;
  end if;

  select count(*) into player_count
    from jsonb_object_keys(game_row.players);

  select coalesce(max(cardinality(m.powers)), 7) into max_players
    from public.maps m where m.id = game_row.map_id;

  if player_count >= max_players then
    raise exception 'Game is full';
  end if;

  select raw_user_meta_data into user_meta
    from auth.users where id = auth.uid();

  player_info = jsonb_build_object(
    'role', 'player',
    'display_name', public.user_display_name(user_meta),
    'joined_at', now()
  );

  update public.games
    set players = players || jsonb_build_object(auth.uid()::text, player_info)
    where id = game_id;

  return (select players from public.games where id = game_id);
end;
$$ language plpgsql security definer;

-- ═══ public.kick_player(uuid, uuid)  — from 20250101000134_sql_helpers.sql
-- kick_player (re-issues 105). Now locks the row up front via lock_owned_game.
create or replace function public.kick_player(game_id uuid, player_id uuid)
returns void as $$
begin
  perform public.lock_owned_game(game_id, 'Only the host can kick players');

  if player_id = auth.uid() then
    raise exception 'Cannot kick yourself';
  end if;

  update public.games
    set players = players - (player_id::text)
    where id = game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.leave_game(uuid)  — from 20250101000104_join_public_game.sql
create or replace function public.leave_game(game_id uuid)
returns void as $$
declare
  game_row public.games;
begin
  select * into game_row from public.games where id = game_id;

  if game_row is null then
    raise exception 'Game not found';
  end if;

  if game_row.created_by = auth.uid() then
    raise exception 'Host cannot leave the game';
  end if;

  update public.games
    set players = players - (auth.uid()::text)
    where id = game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.lock_hosted_game(uuid)  — from 20250101000134_sql_helpers.sql
-- ── lock_hosted_game (re-issues 129) ───────────────────────────────────────────
create or replace function public.lock_hosted_game(p_game_id uuid)
returns public.games as $$
declare g public.games;
begin
  g := public.lock_owned_game(p_game_id);
  if not public.setting_bool(g.settings, 'host_controls', false) then
    raise exception 'Host controls are not enabled for this game';
  end if;
  return g;
end;
$$ language plpgsql security definer;

-- ═══ public.lock_owned_game(uuid, text)  — from 20250101000134_sql_helpers.sql
-- Lock a game row and check the caller created it. p_denied is the caller-specific
-- refusal message.
create or replace function public.lock_owned_game(
  p_game_id uuid,
  p_denied  text default 'Only the game creator can do that'
)
returns public.games as $$
declare g public.games;
begin
  select * into g from public.games where id = p_game_id for update;
  if g is null then raise exception 'Game not found'; end if;
  if g.created_by is distinct from auth.uid() then
    raise exception '%', p_denied;
  end if;
  return g;
end;
$$ language plpgsql security definer;

-- ═══ public.mark_chat_read(bigint)  — from 20250101000137_chat_helpers.sql
-- Advance the caller's read cursor for a channel (drives unread badges).
create or replace function public.mark_chat_read(p_channel_id bigint)
returns void as $$
declare me text;
begin
  me := public.require_chat_member(p_channel_id, 'Not a member of this channel');

  insert into public.chat_reads (channel_id, nation, last_read_at)
  values (p_channel_id, me, now())
  on conflict (channel_id, nation) do update set last_read_at = now();
end;
$$ language plpgsql security definer;

-- ═══ public.maybe_resolve_now(uuid)  — from 20250101000134_sql_helpers.sql
-- maybe_resolve_now (re-issues 131).
create or replace function public.maybe_resolve_now(p_game_id uuid)
returns void as $$
declare g public.games;
begin
  select * into g from public.games where id = p_game_id for update;
  if g is null or g.resolving_at is not null then return; end if;
  if not public.is_order_phase(g.phase) then return; end if;
  if not public.resolution_due(g) then return; end if;

  perform public.fire_adjudicator(p_game_id, '{}'::jsonb, false);
end;
$$ language plpgsql security definer;

-- ═══ public.order_write_guard(uuid, integer, text, text, boolean)  — from 20250101000135_order_write_helpers.sql
-- Validate an own-orders write and return the game row; returns null when the write is
-- stale and p_strict is false (the caller should then do nothing).
create or replace function public.order_write_guard(
  p_game_id uuid,
  p_year    integer,
  p_season  text,
  p_phase   text,
  p_strict  boolean
)
returns public.games as $$
declare g public.games;
begin
  select * into g from public.games where id = p_game_id;
  if g is null then raise exception 'Game not found'; end if;
  if public.player_nation(g.players) is null then
    raise exception 'You are not a player with a nation in this game';
  end if;
  if not public.is_order_phase(g.phase) then
    raise exception 'Game is not in an order-taking phase';
  end if;
  if g.resolving_at is not null then raise exception 'Round is resolving; orders are locked'; end if;

  -- Stale write (the round advanced under an in-flight request). Round params default
  -- to null (guard skipped) for backward compatibility.
  if p_year is not null
     and (g.year, g.season, g.phase) is distinct from (p_year, p_season, p_phase) then
    if p_strict then raise exception 'Round has advanced; reload before submitting'; end if;
    return null;
  end if;

  return g;
end;
$$ language plpgsql;

-- ═══ public.own_chat_draft(bigint)  — from 20250101000137_chat_helpers.sql
-- Does the draft exist (false if not)? Raises 'Not your draft' when it is another
-- nation's. Private.
create or replace function public.own_chat_draft(p_draft_id bigint)
returns boolean as $$
declare g_id uuid; own text;
begin
  select game_id, nation into g_id, own from public.chat_drafts where id = p_draft_id;
  if g_id is null then return false; end if;
  if public.current_nation(g_id) is distinct from own then
    raise exception 'Not your draft';
  end if;
  return true;
end;
$$ language plpgsql security definer stable;

-- ═══ public.phase_deadline(jsonb, text, timestamptz)  — from 20250101000132_phase_deadline.sql
create or replace function public.phase_deadline(p_settings jsonb, p_phase text, p_from timestamptz)
returns timestamptz as $$
  select p_from + make_interval(mins => public.phase_timer_minutes(p_settings, p_phase));
$$ language sql stable;

-- ═══ public.phase_timer_minutes(jsonb, text)  — from 20250101000132_phase_deadline.sql
-- Minutes a phase lasts: settings.phase_timers[phase] when positive, else the
-- DEFAULT_SETTINGS value (movement 24h, retreat/build 12h).
create or replace function public.phase_timer_minutes(p_settings jsonb, p_phase text)
returns integer as $$
  select coalesce(
    nullif(greatest(0, (p_settings -> 'phase_timers' ->> p_phase)::int), 0),
    case p_phase when 'movement' then 1440 else 720 end);
$$ language sql immutable;

-- ═══ public.player_nation(jsonb)  — from 20250101000134_sql_helpers.sql
-- The calling user's nation in a players map (current_nation() without the lookup).
create or replace function public.player_nation(p_players jsonb)
returns text as $$
  select p_players -> (auth.uid()::text) ->> 'nation';
$$ language sql stable;

-- ═══ public.rename_channel(bigint, text)  — from 20250101000137_chat_helpers.sql
-- Rename a channel. Any member may rename it; the public channel cannot be renamed.
create or replace function public.rename_channel(
  p_channel_id bigint,
  p_name       text
) returns void as $$
declare pub boolean;
begin
  select c.is_public into pub from public.chat_channels c where c.id = p_channel_id;
  if not found then raise exception 'Channel not found'; end if;
  if pub then raise exception 'The public channel cannot be renamed'; end if;

  perform public.require_chat_member(p_channel_id, 'Not a member of this channel');

  if p_name is null or length(trim(p_name)) = 0 then raise exception 'A name is required'; end if;
  if length(p_name) > 60 then raise exception 'Name too long (max 60 characters)'; end if;

  update public.chat_channels set name = trim(p_name) where id = p_channel_id;
end;
$$ language plpgsql security definer;

-- ═══ public.rename_chat_draft(bigint, text)  — from 20250101000137_chat_helpers.sql
create or replace function public.rename_chat_draft(
  p_draft_id bigint,
  p_name     text
) returns public.chat_drafts as $$
declare nm text; d public.chat_drafts;
begin
  if not public.own_chat_draft(p_draft_id) then raise exception 'Draft not found'; end if;

  nm := nullif(trim(coalesce(p_name, '')), '');
  if nm is not null and length(nm) > 60 then raise exception 'Name too long (max 60 characters)'; end if;

  update public.chat_drafts set name = nm, updated_at = now()
   where id = p_draft_id
  returning * into d;
  return d;
end;
$$ language plpgsql security definer;

-- ═══ public.require_chat_member(bigint, text)  — from 20250101000137_chat_helpers.sql
-- The caller's nation in a channel they belong to. Raises 'Channel not found', or
-- p_denied when the caller is not a member. Private.
create or replace function public.require_chat_member(p_channel_id bigint, p_denied text)
returns text as $$
declare me text; g_id uuid; mems text[];
begin
  select c.game_id, c.members into g_id, mems
    from public.chat_channels c where c.id = p_channel_id;
  if g_id is null then raise exception 'Channel not found'; end if;

  me := public.current_nation(g_id);
  if me is null or not (me = any(mems)) then raise exception '%', p_denied; end if;
  return me;
end;
$$ language plpgsql security definer stable;

-- ═══ public.resolution_due(games)  — from 20250101000134_sql_helpers.sql
-- resolution_due (re-issues 133).
create or replace function public.resolution_due(g public.games)
returns boolean as $$
  select g.grace_ends_at <= now()
      or (public.all_powers_ready(g.id)
          and (   public.setting_bool(g.settings, 'early_resolution', true)
               or (g.deadline is not null and g.deadline <= now())));
$$ language sql stable security definer;

-- ═══ public.round_rank(integer, text, text)  — from 20250101000129_host_controls.sql
-- Chronological sort key for a round. Mirrors roundRank() in src/lib/adjudicator/fold.ts.
create or replace function public.round_rank(p_year integer, p_season text, p_phase text)
returns integer as $$
  select p_year * 100
       + case p_season when 'Fall' then 10 else 0 end
       + case p_phase when 'retreat' then 1 when 'build' then 2 else 0 end;
$$ language sql immutable;

-- ═══ public.save_draft_orders(uuid, jsonb, integer, text, text)  — from 20250101000135_order_write_helpers.sql
-- ── save_draft_orders (re-issues 118) ──────────────────────────────────────────
-- Autosave the caller's unsubmitted draft. Never touches games.ready, so it stays a
-- draft and is never broadcast.
create or replace function public.save_draft_orders(
  p_game_id uuid,
  p_orders  jsonb,
  p_year    integer default null,
  p_season  text    default null,
  p_phase   text    default null
)
returns void as $$
declare g public.games; me text;
begin
  g := public.order_write_guard(p_game_id, p_year, p_season, p_phase, false);
  if g.id is null then return; end if;  -- stale: the round moved on
  me := public.player_nation(g.players);

  -- Already submitted? Drafts are inert once ready — refuse so an autosave can never
  -- silently overwrite the committed set. Re-submission goes through submit_orders.
  if public.is_ready(g.ready, me) then return; end if;

  perform public.upsert_own_orders(g, me, p_orders);
end;
$$ language plpgsql security definer;

-- ═══ public.send_chat_message(bigint, text)  — from 20250101000145_chat_body_max.sql
create or replace function public.send_chat_message(
  p_channel_id bigint,
  p_body       text
) returns public.chat_messages as $$
declare
  me  text;
  msg public.chat_messages;
begin
  me := public.require_chat_member(p_channel_id, 'You are not a member of this channel');

  if p_body is null or length(trim(p_body)) = 0 then
    raise exception 'Message is empty';
  end if;
  if length(p_body) > 5000 then
    raise exception 'Message too long (max 5000 characters)';
  end if;

  insert into public.chat_messages (channel_id, sender, body)
  values (p_channel_id, me, trim(p_body))
  returning * into msg;

  -- Online-only, full-payload live delivery. Topic must match the client channel name.
  perform realtime.send(to_jsonb(msg), 'msg', 'chat:' || p_channel_id::text, true);

  insert into public.chat_reads (channel_id, nation, last_read_at)
  values (p_channel_id, me, now())
  on conflict (channel_id, nation) do update set last_read_at = excluded.last_read_at;

  return msg;
end;
$$ language plpgsql security definer;

-- ═══ public.set_deadline(uuid, timestamptz)  — from 20250101000134_sql_helpers.sql
-- set_deadline (re-issues 129).
create or replace function public.set_deadline(p_game_id uuid, p_deadline timestamptz)
returns void as $$
declare g public.games;
begin
  g := public.lock_hosted_game(p_game_id);
  if not public.is_order_phase(g.phase) then
    raise exception 'Game is not in an order-taking phase';
  end if;
  if g.resolving_at is not null then
    raise exception 'Round is resolving; the deadline is locked';
  end if;
  update public.games set deadline = p_deadline, updated_at = now() where id = p_game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.set_display_name(text)  — from 20250101000140_display_name_fix.sql
-- set_display_name (re-issues 139): its local `name` was ambiguous with games.name in
-- the roster update. Renamed to v_name.
create or replace function public.set_display_name(p_name text)
returns text as $$
declare
  uid    text := auth.uid()::text;
  v_name text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
begin
  if uid is null then raise exception 'Not signed in'; end if;
  if char_length(v_name) < 2 or char_length(v_name) > 32 then
    raise exception 'Name must be 2–32 characters';
  end if;

  update auth.users
     set raw_user_meta_data = coalesce(raw_user_meta_data, '{}') || jsonb_build_object('display_name', v_name)
   where id = auth.uid();

  -- Roster entries are objects; a private-game invite can still hold a bare 'pending'.
  update public.games
     set players = jsonb_set(players, array[uid, 'display_name'], to_jsonb(v_name))
   where players ? uid
     and jsonb_typeof(players -> uid) = 'object';

  return v_name;
end;
$$ language plpgsql security definer;

-- ═══ public.set_draw_vote(uuid, text[], boolean)  — from 20250101000141_draw_votes.sql
-- ── set_draw_vote ─────────────────────────────────────────────────────────────
-- Record the caller's vote: p_concede, or the powers to share a tie with (the caller
-- is added; an empty or self-only set means solo). Returns whether the game ended.
create or replace function public.set_draw_vote(
  p_game_id uuid,
  p_members text[]  default null,
  p_concede boolean default false
)
returns boolean as $$
declare
  g         public.games;
  my_nation text;
  alive     text[];
  members   text[];
begin
  select * into g from public.games where id = p_game_id;
  if not found then raise exception 'Game not found'; end if;
  my_nation := public.player_nation(g.players);
  if my_nation is null then raise exception 'Only players can vote'; end if;
  if not public.is_order_phase(g.phase) then raise exception 'The game is not running'; end if;
  alive := public.surviving_nations(g);
  if not my_nation = any(alive) then raise exception 'Eliminated powers no longer vote'; end if;

  if p_concede then
    members := null;
  else
    members := (select array_agg(distinct m order by m)
                  from unnest(coalesce(p_members, '{}') || array[my_nation]) m);
    if exists (select 1 from unnest(members) m where not m = any(alive)) then
      raise exception 'A tie can only include powers still in the game';
    end if;
  end if;

  if not p_concede and members = array[my_nation] then
    delete from public.draw_votes where game_id = p_game_id and nation = my_nation;  -- solo
  else
    insert into public.draw_votes (game_id, nation, members, updated_at)
    values (p_game_id, my_nation, members, now())
    on conflict (game_id, nation) do update set members = excluded.members, updated_at = now();
  end if;

  return public.settle_draw(p_game_id);
end;
$$ language plpgsql security definer;

-- ═══ public.set_grace_ends_at()  — from 20250101000134_sql_helpers.sql
-- set_grace_ends_at (re-issues 133): body unchanged, now security definer (see above).
create or replace function public.set_grace_ends_at()
returns trigger as $$
begin
  new.grace_ends_at := new.deadline + make_interval(mins => public.grace_minutes(new.settings));
  return new;
end;
$$ language plpgsql security definer;

-- ═══ public.setting_bool(jsonb, text, boolean)  — from 20250101000134_sql_helpers.sql
-- A boolean game setting, with the default for a missing key. Mirrors DEFAULT_SETTINGS.
create or replace function public.setting_bool(p_settings jsonb, p_key text, p_default boolean)
returns boolean as $$
  select coalesce((p_settings ->> p_key)::boolean, p_default);
$$ language sql immutable;

-- ═══ public.settle_draw(uuid)  — from 20250101000141_draw_votes.sql
-- End the game if the survivors have agreed. Service-only (no grant): called from
-- set_draw_vote and apply_resolution. Returns whether the game ended.
create or replace function public.settle_draw(p_game_id uuid)
returns boolean as $$
declare
  g       public.games;
  outcome text[];
begin
  select * into g from public.games where id = p_game_id for update;
  if not found or not public.is_order_phase(g.phase) or g.resolving_at is not null then
    return false;
  end if;
  outcome := public.draw_outcome(g);
  if outcome is null then return false; end if;

  update public.games
     set phase      = 'complete',
         deadline   = null,
         ready      = '{}'::jsonb,
         result     = jsonb_build_object(
                        'kind',    case when cardinality(outcome) = 1 then 'concession' else 'draw' end,
                        'nations', to_jsonb(outcome),
                        'year',    g.year,
                        'season',  g.season,
                        'phase',   g.phase),
         updated_at = now()
   where id = p_game_id;
  return true;
end;
$$ language plpgsql security definer;

-- ═══ public.start_game(uuid)  — from 20250101000143_first_turn.sql
-- ── start_game (re-issues 138; only the deadline line changes) ─────────────────
create or replace function public.start_game(p_game_id uuid)
returns void as $$
declare
  g           public.games;
  powers      text[];
  start_year  integer;
  random_mode boolean;
  free        text[];
  next_free   integer := 1;
  p           record;
  assigned    jsonb;
begin
  g := public.lock_owned_game(p_game_id, 'Only the game creator can start the game');
  if g.phase <> 'lobby' then raise exception 'Game has already started'; end if;

  select m.powers, m.starting_year into powers, start_year
    from public.maps m where m.id = g.map_id;
  if powers is null then raise exception 'Unknown map: %', g.map_id; end if;

  if (select count(*) from jsonb_object_keys(g.players)) > array_length(powers, 1) then
    raise exception 'Too many players for this map (max %)', array_length(powers, 1);
  end if;

  random_mode := public.setting_bool(g.settings, 'random_nations', false);

  -- Powers nobody validly claimed, shuffled.
  select coalesce(array_agg(pw order by random()), '{}') into free
    from unnest(powers) pw
   where random_mode
      or not (pw = any(coalesce(public.game_nations(g.players), '{}')));

  assigned := g.players;
  for p in select key as uid, value ->> 'nation' as claimed from jsonb_each(g.players) loop
    if random_mode or p.claimed is null or not (p.claimed = any(powers)) then
      assigned := jsonb_set(assigned, array[p.uid, 'nation'], to_jsonb(free[next_free]));
      next_free := next_free + 1;
    end if;
  end loop;

  update public.games
     set phase        = 'movement',
         year         = start_year,
         season       = 'Spring',
         players      = assigned,
         snapshot     = null,
         ready        = '{}'::jsonb,
         resolving_at = null,
         deadline     = public.first_turn_deadline(g.settings, now()),
         updated_at   = now()
   where id = p_game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.submit_orders(uuid, jsonb, boolean, integer, text, text)  — from 20250101000135_order_write_helpers.sql
-- ── submit_orders (re-issues 119) ──────────────────────────────────────────────
-- Upsert the caller's orders for the current round and set (or clear) ready.
create or replace function public.submit_orders(
  p_game_id uuid,
  p_orders  jsonb,
  p_ready   boolean default false,
  p_year    integer default null,
  p_season  text    default null,
  p_phase   text    default null
)
returns void as $$
declare
  g         public.games;
  my_nation text;
begin
  g := public.order_write_guard(p_game_id, p_year, p_season, p_phase, true);
  my_nation := public.player_nation(g.players);

  perform public.upsert_own_orders(g, my_nation, p_orders);

  update public.games
     set ready = case when p_ready then ready || jsonb_build_object(my_nation, true)
                      else ready - my_nation end,
         updated_at = now()
   where id = p_game_id;

  -- Last power in? Resolve immediately rather than waiting for the cron tick.
  if p_ready then perform public.maybe_resolve_now(p_game_id); end if;
end;
$$ language plpgsql security definer;

-- ═══ public.surviving_nations(games)  — from 20250101000141_draw_votes.sql
-- ── Survivors ─────────────────────────────────────────────────────────────────
-- Assigned nations still on the board (a unit or a supply center). Before the first
-- resolution (no snapshot) everyone is alive.
create or replace function public.surviving_nations(g public.games)
returns text[] as $$
  select coalesce(array_agg(n order by n), '{}')
    from unnest(coalesce(public.game_nations(g.players), '{}')) as n
   where g.snapshot is null
      or exists (select 1 from jsonb_array_elements(coalesce(g.snapshot -> 'units', '[]')) u
                  where u ->> 'nation' = n)
      or exists (select 1 from jsonb_each_text(coalesce(g.snapshot -> 'supplyCenters', '{}')) s
                  where s.value = n);
$$ language sql stable;

-- ═══ public.tick_due_games()  — from 20250101000134_sql_helpers.sql
-- tick_due_games (re-issues 131).
create or replace function public.tick_due_games()
returns void as $$
declare g record;
begin
  -- Reap stale locks from crashed/never-completed resolutions FIRST (see cron.sql).
  update public.games
     set resolving_at = null
   where resolving_at is not null
     and resolving_at < now() - interval '5 minutes';

  for g in
    select id
      from public.games
     where public.is_order_phase(phase)
       and resolving_at is null
       and public.resolution_due(games)
     for update skip locked
  loop
    -- Unconfigured engine: nothing can be fired this tick.
    exit when not public.fire_adjudicator(g.id, '{}'::jsonb, false);
  end loop;
end;
$$ language plpgsql security definer;

-- ═══ public.update_game_settings(uuid, jsonb)  — from 20250101000144_drop_dead_settings.sql
-- update_game_settings (re-issues 134): allow_spectators leaves the mid-game allowlist.
create or replace function public.update_game_settings(p_game_id uuid, p_settings jsonb)
returns void as $$
declare
  g     public.games;
  patch jsonb;
begin
  g := public.lock_owned_game(p_game_id, 'Only the game creator can change settings');

  if g.phase = 'lobby' then
    patch := coalesce(p_settings, '{}'::jsonb);
  else
    if not public.setting_bool(g.settings, 'host_controls', false) then
      raise exception 'Settings are locked once the game has started';
    end if;
    -- Mid-game: keep only the mutable keys from the supplied patch.
    patch := (
      select coalesce(jsonb_object_agg(k, p_settings -> k), '{}'::jsonb)
        from jsonb_object_keys(coalesce(p_settings, '{}'::jsonb)) k
       where k in ('phase_timers', 'early_resolution', 'grace_period'));
  end if;

  update public.games
     set settings = settings || patch,
         updated_at = now()
   where id = p_game_id;
end;
$$ language plpgsql security definer;

-- ═══ public.update_updated_at()  — from 20250101000101_schema.sql
-- Auto-update updated_at on row changes
create or replace function public.update_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

-- ═══ public.upsert_chat_draft(uuid, text[], text, text)  — from 20250101000145_chat_body_max.sql
create or replace function public.upsert_chat_draft(
  p_game_id uuid,
  p_members text[],
  p_name    text,
  p_body    text
) returns public.chat_drafts as $$
declare
  me        text;
  canonical text[];
  nm        text;
  d         public.chat_drafts;
begin
  canonical := public.canonical_channel_members(p_game_id, p_members);
  me        := public.current_nation(p_game_id);

  nm := nullif(trim(coalesce(p_name, '')), '');
  if nm is not null and length(nm) > 60 then raise exception 'Name too long (max 60 characters)'; end if;
  if p_body is not null and length(p_body) > 5000 then raise exception 'Message too long (max 5000 characters)'; end if;

  update public.chat_drafts
     set body = coalesce(p_body, ''), updated_at = now()
   where game_id = p_game_id and nation = me and members = canonical
     and coalesce(name, '') = coalesce(nm, '')
  returning * into d;

  if not found then
    insert into public.chat_drafts (game_id, nation, members, name, body)
    values (p_game_id, me, canonical, nm, coalesce(p_body, ''))
    returning * into d;
  end if;

  return d;
end;
$$ language plpgsql security definer;

-- ═══ public.upsert_own_orders(games, text, jsonb)  — from 20250101000135_order_write_helpers.sql
-- Write a nation's order set into its single row for the game's current round. A
-- resolved row is never touched (the log is immutable).
create or replace function public.upsert_own_orders(p_game public.games, p_nation text, p_orders jsonb)
returns void as $$
begin
  insert into public.orders (game_id, year, season, phase, nation, orders, submitted_by, resolved)
  values (p_game.id, p_game.year, p_game.season, p_game.phase, p_nation,
          coalesce(p_orders, '[]'::jsonb), auth.uid(), false)
  on conflict (game_id, year, season, phase, nation)
  do update set orders = excluded.orders, submitted_by = excluded.submitted_by, updated_at = now()
  where public.orders.resolved = false;
end;
$$ language plpgsql;

-- ═══ public.user_display_name(jsonb)  — from 20250101000139_display_name.sql
-- The name to show for a user's metadata: the chosen one, else the provider's.
create or replace function public.user_display_name(p_meta jsonb)
returns text as $$
  select coalesce(p_meta ->> 'display_name', p_meta ->> 'full_name', p_meta ->> 'name');
$$ language sql immutable;
